# Таблица клиентов и специальные действия с ней.
from final_project_sql_m26_555.dbtable import DbTable


class ClientsTable(DbTable):
    def table_name(self):
        return self.dbconn.prefix + "clients"

    def columns(self):
        return {
            "id_client": ["integer", "GENERATED BY DEFAULT AS IDENTITY", "PRIMARY KEY"],
            "name_legal_entity": ["varchar(200)", "NOT NULL"],
            "bank_details": ["text", "NOT NULL"],
        }

    def primary_key(self):
        return ["id_client"]

    def column_names_without_id(self):
        return ["name_legal_entity", "bank_details"]

    def all(self):
        sql = f"SELECT id_client, name_legal_entity, bank_details FROM {self.table_name()} ORDER BY id_client"
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql)
            return cur.fetchall()

    def find_by_position(self, num):
        sql = f"SELECT id_client, name_legal_entity, bank_details FROM {self.table_name()} ORDER BY id_client LIMIT 1 OFFSET %s"
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (num - 1,))
            return cur.fetchone()

    def add(self, name, bank_details):
        self.insert_one([name, bank_details])

    def update(self, client_id, name, bank_details):
        sql = f"UPDATE {self.table_name()} SET name_legal_entity = %s, bank_details = %s WHERE id_client = %s"
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (name, bank_details, client_id))
            changed = cur.rowcount
        self.dbconn.conn.commit()
        return changed

    def delete(self, client_id):
        sql = f"DELETE FROM {self.table_name()} WHERE id_client = %s"
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (client_id,))
            changed = cur.rowcount
        self.dbconn.conn.commit()
        return changed

    def has_products(self, client_id):
        sql = f"SELECT EXISTS (SELECT 1 FROM {self.dbconn.prefix}product WHERE id_client = %s)"
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (client_id,))
            return cur.fetchone()[0]
